import fs from 'fs'
import generateRss from '@/lib/generate-rss'
import { MDXLayoutRenderer } from '@/components/MDXComponents'
import { formatSlug, getAllFilesFrontMatter, getFileBySlug, getFiles } from '@/lib/mdx'
import { CourseSEO } from '@/components/SEO'
import siteMetadata from '@/data/siteMetadata'
import path from 'path'

const DEFAULT_LAYOUT = 'CourseSimple'

export async function getStaticPaths() {
  const posts = getFiles('courses')
  return {
    paths: posts.map((p) => ({
      params: {
        slug: formatSlug(p).split('/'),
      },
    })),
    fallback: false,
  }
}

export async function getStaticProps({ params }) {
  const all = await getAllFilesFrontMatter('courses')
  const allPosts = all.reverse()
  const post = await getFileBySlug('courses', params.slug.join('/'))
  const course = params.slug[0]
  const sameCoursePosts = allPosts
    .filter((p) => p.draft !== true && p.slug.split('/')[0] === course)
    .sort((a, b) => a.index - b.index)
  const postIndex = post.frontMatter.index
  const prev =
    allPosts.filter((p) => p.slug.split('/')[0] === course && p.index === postIndex - 1)[0] || null
  const next =
    allPosts.filter((p) => p.slug.split('/')[0] === course && p.index === postIndex + 1)[0] || null

  const authorList = post.frontMatter.authors || ['default']
  const authorPromise = authorList.map(async (author) => {
    const authorResults = await getFileBySlug('authors', [author])
    return authorResults.frontMatter
  })
  const authorDetails = await Promise.all(authorPromise)

  // Get mentor details if mentors field exists in frontMatter
  let mentorDetails = []
  if (post.frontMatter.mentors && Array.isArray(post.frontMatter.mentors)) {
    const mentorPromise = post.frontMatter.mentors.map(async (mentor) => {
      const mentorResult = await getFileBySlug('authors', [mentor])
      return mentorResult.frontMatter
    })
    mentorDetails = await Promise.all(mentorPromise)
  }

  const courses = await getAllFilesFrontMatter('courses')
  let otherCourses = courses
    .filter((c) => c.index === 0) // Only main course pages
    .filter((c) => c.slug !== post.slug) // Exclude current course
    .sort((a, b) => {
      // Sort by priority: paid courses first, then free courses
      if (a.isFree === b.isFree) return 0
      return a.isFree ? 1 : -1
    })
    .slice(0, 6) // Limit to 6 courses

  // rss
  if (allPosts.length > 0) {
    const rss = generateRss(allPosts, `courses/${course}/feed.xml`)
    const rssPath = path.join(process.cwd(), 'public', 'courses', course)
    fs.mkdirSync(rssPath, { recursive: true })
    fs.writeFileSync(path.join(rssPath, 'feed.xml'), rss)
  }

  return {
    props: {
      post,
      authorDetails,
      mentorDetails,
      posts: sameCoursePosts,
      otherCourses: otherCourses,
      prev: prev,
      next: next,
    },
  }
}

export default function Course({
  post,
  authorDetails,
  mentorDetails,
  posts,
  otherCourses,
  prev,
  next,
}) {
  const { mdxSource, toc, frontMatter } = post
  const { title, summary, date, lastmod, images, slug, index, price, startDate, duration } =
    frontMatter

  // Generate proper SEO data
  const courseUrl = `${siteMetadata.siteUrl}/courses/${slug}`
  const courseImages = images && images.length > 0 ? images : [siteMetadata.socialBanner]
  const courseDescription = summary || `${title} - Khóa học tại VNTechies`
  const courseTitle = `${title} | VNTechies`

  return (
    <>
      <CourseSEO
        title={courseTitle}
        summary={courseDescription}
        date={startDate || date}
        lastmod={lastmod}
        url={courseUrl}
        images={courseImages}
        courseItems={index === 0 ? posts : null}
        canonicalUrl={courseUrl}
        price={price}
        duration={duration}
      />
      <MDXLayoutRenderer
        layout={frontMatter.layout || DEFAULT_LAYOUT}
        toc={toc}
        mdxSource={mdxSource}
        frontMatter={frontMatter}
        authorDetails={authorDetails}
        mentorDetails={mentorDetails}
        posts={posts}
        otherCourses={otherCourses}
        prev={prev}
        next={next}
      />
    </>
  )
}
import { escape } from '@/lib/utils/htmlEscaper'

import siteMetadata from '@/data/siteMetadata'

const generateRssItem = (post) => `
  <item>
    <guid>${siteMetadata.siteUrl}/blog/${post.slug}</guid>
    <title>${escape(post.title)}</title>
    <link>${siteMetadata.siteUrl}/blog/${post.slug}</link>
    ${post.summary && `<description>${escape(post.summary)}</description>`}
    <pubDate>${new Date(post.date).toUTCString()}</pubDate>
    <author>${siteMetadata.email} (${siteMetadata.author})</author>
    ${post.tags && post.tags.map((t) => `<category>${t}</category>`).join('')}
  </item>
`

const generateRss = (posts, page = 'feed.xml') => `
  <rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
    <channel>
      <title>${escape(siteMetadata.title)}</title>
      <link>${siteMetadata.siteUrl}/blog</link>
      <description>${escape(siteMetadata.description)}</description>
      <language>${siteMetadata.language}</language>
      <managingEditor>${siteMetadata.email} (${siteMetadata.author})</managingEditor>
      <webMaster>${siteMetadata.email} (${siteMetadata.author})</webMaster>
      <lastBuildDate>${new Date(posts[0].date).toUTCString()}</lastBuildDate>
      <atom:link href="${siteMetadata.siteUrl}/${page}" rel="self" type="application/rss+xml"/>
      ${posts.map(generateRssItem).join('')}
    </channel>
  </rss>
`
export default generateRss
      </Head>
    </>
  )
}

export const BlogSEO = ({
  authorDetails,
  title,
  summary,
  date,
  lastmod,
  url,
  images = [],
  canonicalUrl,
}) => {
  const router = useRouter()
  const publishedAt = new Date(date).toISOString()
  const modifiedAt = new Date(lastmod || date).toISOString()
  let imagesArr =
    images.length === 0
      ? [siteMetadata.socialBanner]
      : typeof images === 'string'
      ? [images]
      : images

  const featuredImages = imagesArr.map((img) => {
    return {
      '@type': 'ImageObject',
      url: img.includes('http') ? img : siteMetadata.siteUrl + img,
    }
  })

  let authorList
  if (authorDetails) {
    authorList = authorDetails.map((author) => {
      return {
        '@type': 'Person',
        name: author.name,
        url: author.url,
      }
    })
  } else {
    authorList = {
      '@type': 'Person',
      name: siteMetadata.author,
    }
  }

  const structuredData = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    mainEntityOfPage: {
      '@type': 'WebPage',
      '@id': url,
    },
    headline: title,
    image: featuredImages,
    datePublished: publishedAt,
    dateModified: modifiedAt,
    author: authorList,
    publisher: {
      '@type': 'Organization',
      name: siteMetadata.author,
      logo: {
        '@type': 'ImageObject',
        url: `${siteMetadata.siteUrl}${siteMetadata.siteLogo}`,
      },
    },
    description: summary,
  }

  const twImageUrl = featuredImages[0].url

  return (
    <>
      <CommonSEO
        title={title}
        description={summary}
        ogType="article"
        ogImage={featuredImages}
        twImage={twImageUrl}
        canonicalUrl={canonicalUrl}
      />
      <Head>
        {date && <meta property="article:published_time" content={publishedAt} />}
        {lastmod && <meta property="article:modified_time" content={modifiedAt} />}
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify(structuredData, null, 2),
          }}
        />
      </Head>
    </>
  )
}

export const CourseSEO = ({
  title,
  courseItems,
  summary,
  url,
  lastmod,
  date,
  canonicalUrl,
  images = [],
  showCanonical,
  price,
  duration,
}) => {
  const router = useRouter()
  const publishedAt = new Date(date).toISOString()
  const modifiedAt = new Date(lastmod || date).toISOString()
  let imagesArr =
    images.length === 0
      ? [siteMetadata.socialBanner]
      : typeof images === 'string'
      ? [images]
      : images
  const featuredImages = imagesArr.map((img) => {
    return {
      '@type': 'ImageObject',
      url: img.includes('http') ? img : siteMetadata.siteUrl + img,
    }
  })

  const provider = {
    '@type': 'Organization',
    name: `${siteMetadata.author}`,
    sameAs: `${siteMetadata.siteUrl}`,
  }

  var structuredData = {}
  if (courseItems) {
    const items = []
    courseItems.map((c) => {
      const item = {
        '@type': 'ListItem',
        position: `${c.index}`,
        item: {
          '@type': 'Course',
          url: `${siteMetadata.siteUrl}${router.asPath}`,
          name: c.title,
          description: c.summary,
          provider: provider,
        },
      }

      items.push(item)
    })
    structuredData = {
      '@context': 'https://schema.org',
      '@type': 'ItemList',
      mainEntityOfPage: {
        '@type': 'WebPage',
        '@id': url,
      },
      itemListElement: items,
    }
  } else {
    // Parse price from Vietnamese format (e.g., "8.000.000 VNĐ" -> "8000000")
    const parsedPrice = price ? price.replace(/[^0-9]/g, '') || '0' : '0'
    const currency = price && price.includes('VNĐ') ? 'VND' : 'USD'

    structuredData = {
      '@context': 'https://schema.org',
      '@type': 'Course',
      mainEntityOfPage: {
        '@type': 'WebPage',
        '@id': url,
      },
      name: title,
      description: summary,
      provider: {
        '@type': 'Organization',
        name: 'VNTechies',
        url: 'https://vntechies.dev',
        logo: {
          '@type': 'ImageObject',
          url: `${siteMetadata.siteUrl}${siteMetadata.siteLogo}`,
        },
      },
      hasCourseInstance: {
        '@type': 'CourseInstance',
        courseMode: 'online',
        startDate: date
          ? new Date(date).toISOString().split('T')[0]
          : new Date().toISOString().split('T')[0],
        location: 'Vietnam',
        instructor: {
          '@type': 'Organization',
          name: 'VNTechies',
        },
      },
      offers: {
        '@type': 'Offer',
        url: url,
        price: parsedPrice,
        priceCurrency: currency,
        availability: 'https://schema.org/InStock',
        validFrom: new Date().toISOString().split('T')[0],
      },
      ...(duration && { timeRequired: duration }),
      ...(featuredImages.length > 0 && { image: featuredImages[0].url }),
    }
  }
  const twImageUrl = featuredImages[0].url
  const ogImageUrl = featuredImages[0].url

  return (
    <>
      <CommonSEO
        title={title}
        description={summary}
        ogType="course"
        ogImage={ogImageUrl}
        twImage={twImageUrl}
        canonicalUrl={canonicalUrl}
        showCanonical={showCanonical}
      />
      <Head>
        {date && <meta property="course:published_time" content={publishedAt} />}
        {lastmod && <meta property="course:modified_time" content={modifiedAt} />}
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify(structuredData, null, 2),
          }}
        />
      </Head>
    </>
  )
}

