export default function PostLayout({ frontMatter, authorDetails, next, prev, children }) {
  const { slug, date, title, tags } = frontMatter

  return (
    <SectionContainer>
      <BlogSEO
        url={`${siteMetadata.siteUrl}/blog/${slug}`}
        authorDetails={authorDetails}
        {...frontMatter}
      />
      <ScrollTopAndComment />
      <SummaryButton
        content={
          typeof children === 'string' ? children : children?.props?.children?.toString() || title
        }
      />

      {/* overflow-x-clip (not hidden) so the sidebar can stick */}
      <article className="surface-panel overflow-x-clip px-4 py-8 sm:px-8 lg:px-10">
        <header className="mx-auto max-w-3xl text-center">
---
name: Anh Cloud
avatar: /static/images/authors/anhcloud.jpeg
occupation: Thầy đồ
company: VNTechies
email: anhcloud@vntechies.dev
twitter: https://twitter.com/vn_techies
